'use strict';
(async()=>{const slot=document.querySelector('#signup-slot');if(!slot)return;try{const response=await fetch('/api/config',{cache:'no-store'});if(!response.ok)throw Error();const config=await response.json();if(!config.signupEnabled)return;document.querySelector('#signup-intro').textContent='Australian offers, checked before publishing. Confirm your address before the first alert.';document.querySelector('#signup-closed').hidden=true;slot.hidden=false;const form=slot.querySelector('form'),status=slot.querySelector('[role=status]'),submit=form.querySelector('button');let widget;window.fluqonSignupReady=()=>{widget=window.turnstile.render('#signup-security',{sitekey:config.sitekey,theme:'dark',action:'subscribe',callback:()=>{submit.disabled=false;},'expired-callback':()=>{submit.disabled=true;},'error-callback':()=>{submit.disabled=true;status.textContent='Security check unavailable. Please try again.';}});};const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?onload=fluqonSignupReady&render=explicit';document.head.append(script);form.addEventListener('submit',async event=>{event.preventDefault();submit.disabled=true;status.textContent='Requesting confirmation…';try{const r=await fetch('/api/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:form.email.value,consent:form.consent.checked,consent_version:'2026-10-19',turnstile:window.turnstile.getResponse(widget)})});const result=await r.json();if(!r.ok)throw Error(result.error);status.textContent=result.message;form.reset();}catch(error){status.textContent=error.message;}finally{window.turnstile.reset(widget);}});}catch{/* Closed is the safe default when delivery cannot be checked. */}})();
